package com.ynxweb4.video;
import android.content.Context;
import org.json.JSONObject;
import java.nio.charset.StandardCharsets;
import java.util.UUID;

// Ordinary account-owned viewer data, never credentials or a signing namespace.
// Watch totals are not resume positions. Corrupt records remain held in place.
final class VideoViewerState {
 private final Context context;private final VideoApi api;private final String name;
 VideoViewerState(Context context,VideoApi api)throws Exception{api.requireCurrent();this.context=context;this.api=api;name="ynx_video_viewer_v2_"+VideoApi.digest(api.identity.account.getBytes(StandardCharsets.UTF_8));}
 private JSONObject read()throws Exception{api.requireCurrent();String raw=context.getSharedPreferences(name,0).getString("state",null);if(raw==null)return new JSONObject().put("version",1).put("account",api.identity.account).put("resume",new JSONObject());if(raw.length()>524288)throw new SecurityException("Original viewer state exceeds limit");JSONObject state=new JSONObject(raw);if(state.getInt("version")!=1||!api.identity.account.equals(state.getString("account"))||!(state.get("resume") instanceof JSONObject))throw new SecurityException("Original viewer state unavailable; preserve record");return state;}
 private void write(JSONObject state)throws Exception{api.requireCurrent();String raw=state.toString();if(raw.length()>524288)throw new IllegalStateException("Viewer state capacity reached; preserve existing records");if(!context.getSharedPreferences(name,0).edit().putString("state",raw).commit()||!raw.equals(context.getSharedPreferences(name,0).getString("state",null)))throw new IllegalStateException("Original viewer state write unconfirmed");api.requireCurrent();}
 synchronized JSONObject playback(String id)throws Exception{synchronized(VideoViewerState.class){if(!id.matches("[A-Za-z0-9_-]+"))throw new SecurityException("Original video ID required");JSONObject state=read(),row=state.getJSONObject("resume").optJSONObject(id);if(row!=null){if(!row.getString("playbackId").matches("[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}")||row.getInt("position")<0)throw new SecurityException("Original resume state unavailable");return new JSONObject(row.toString());}row=new JSONObject().put("playbackId",UUID.randomUUID().toString()).put("position",0);state.getJSONObject("resume").put(id,row);write(state);return row;}}
 synchronized JSONObject position(String id,String playbackId,int position,int seconds,boolean completed)throws Exception{synchronized(VideoViewerState.class){JSONObject state=read(),row=state.getJSONObject("resume").getJSONObject(id);if(!playbackId.equals(row.getString("playbackId")))throw new SecurityException("Original playback retired");if(completed)state.getJSONObject("resume").remove(id);else row.put("position",Math.max(0,position));
        if(seconds<0||seconds>86400)throw new SecurityException("Observed watch increment required");JSONObject pending=null;
        if(seconds>0||completed){org.json.JSONArray batches=state.optJSONArray("watchPending");if(batches==null){batches=new org.json.JSONArray();state.put("watchPending",batches);}pending=new JSONObject().put("key",UUID.randomUUID().toString()).put("videoId",id).put("playbackId",playbackId).put("seconds",seconds).put("completed",completed);batches.put(pending);}
        write(state);return pending;}}
 synchronized org.json.JSONArray watchPending()throws Exception{synchronized(VideoViewerState.class){org.json.JSONArray items=read().optJSONArray("watchPending");return items==null?new org.json.JSONArray():new org.json.JSONArray(items.toString());}}
 synchronized void finishWatch(JSONObject original)throws Exception{synchronized(VideoViewerState.class){JSONObject state=read();org.json.JSONArray items=state.getJSONArray("watchPending"),remaining=new org.json.JSONArray();boolean found=false;for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);if(original.getString("key").equals(item.getString("key"))){if(!NativeProductState.canonical(original).equals(NativeProductState.canonical(item)))throw new SecurityException("Original watch result changed");found=true;}else remaining.put(item);}if(!found)throw new SecurityException("Original watch result retired");state.put("watchPending",remaining);write(state);}}
 synchronized JSONObject playlistDraft()throws Exception{synchronized(VideoViewerState.class){JSONObject draft=read().optJSONObject("playlistDraft");if(draft==null)return null;if(!draft.getString("key").matches("[0-9a-f-]{36}")||draft.getString("name").isEmpty())throw new SecurityException("Original playlist draft unavailable");return new JSONObject(draft.toString());}}
 synchronized JSONObject reservePlaylist(String requested)throws Exception{synchronized(VideoViewerState.class){String value=requested.trim();if(value.isEmpty()||value.length()>1024)throw new IllegalArgumentException("Playlist name required");JSONObject state=read(),draft=state.optJSONObject("playlistDraft");if(draft!=null){if(!value.equals(draft.getString("name")))throw new IllegalStateException("Finish the original playlist draft before replacing it");return new JSONObject(draft.toString());}draft=new JSONObject().put("key",UUID.randomUUID().toString()).put("name",value);state.put("playlistDraft",draft);write(state);return draft;}}
 synchronized void finishPlaylist(JSONObject original)throws Exception{synchronized(VideoViewerState.class){JSONObject state=read(),pending=state.optJSONObject("playlistDraft");if(pending==null||!NativeProductState.canonical(pending).equals(NativeProductState.canonical(original)))throw new SecurityException("Original playlist result retired");state.remove("playlistDraft");write(state);}}
 synchronized void deleteMyData()throws Exception{synchronized(VideoViewerState.class){api.requireCurrent();if(!context.getSharedPreferences(name,0).edit().remove("state").commit()||context.getSharedPreferences(name,0).getString("state",null)!=null)throw new IllegalStateException("Original viewer data deletion unconfirmed");api.requireCurrent();}}
}
